(function () { function placeActionTooltip(e) { const button = e.target.closest?.('#csvDownload,#clear'); if (!button) return; document.querySelectorAll('#chartHoverValue,#uiTip').forEach(tip => { if (getComputedStyle(tip).display === 'none') return; const gap = 12, margin = 8, w = tip.offsetWidth, h = tip.offsetHeight; let left = e.clientX - w - gap, top = e.clientY + gap; left = Math.max(margin, Math.min(innerWidth - w - margin, left)); top = Math.max(margin, Math.min(innerHeight - h - margin, top)); tip.style.left = left + 'px'; tip.style.top = top + 'px' }) } document.addEventListener('pointermove', placeActionTooltip); document.addEventListener('mousemove', placeActionTooltip) })();

/* Robust maximized/full-screen detection across Windows scaling levels. */
(() => {
  let timer = 0;

  function setWindowMode() {
    const root = document.documentElement;
    const body = document.body;
    if (!root || !body) return;

    const availW = Number(screen.availWidth || screen.width || 0);
    const availH = Number(screen.availHeight || screen.height || 0);
    const outerW = Number(window.outerWidth || 0);
    const outerH = Number(window.outerHeight || 0);

    const widthRatio = availW ? outerW / availW : 0;
    const heightRatio = availH ? outerH / availH : 0;
    const nearScreenOrigin = window.screenX <= 16 && window.screenY <= 16;
    const maximized = widthRatio >= 0.94 && heightRatio >= 0.90 && nearScreenOrigin;
    const fullscreen = Boolean(document.fullscreenElement) ||
      (window.innerWidth >= screen.width * 0.98 && window.innerHeight >= screen.height * 0.90);
    const fixedMode = maximized || fullscreen;

    root.classList.toggle("is-maximized-mode", fixedMode);
    body.classList.toggle("is-maximized-mode", fixedMode);
    root.dataset.windowMode = fixedMode ? "maximized" : "windowed";
  }

  function scheduleWindowMode() {
    clearTimeout(timer);
    timer = setTimeout(setWindowMode, 120);
  }

  window.addEventListener("resize", scheduleWindowMode, { passive: true });
  window.addEventListener("orientationchange", scheduleWindowMode, { passive: true });
  window.addEventListener("focus", scheduleWindowMode);
  document.addEventListener("fullscreenchange", setWindowMode);
  document.addEventListener("DOMContentLoaded", setWindowMode, { once: true });
  window.addEventListener("load", setWindowMode, { once: true });
  setWindowMode();
})();
if ("serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker
      .register("./service-worker.js")
      .catch(error => {
        console.error("Service Worker registration failed:", error);
      });
  });
}
